dict(id="S21", page="@changyin", speaker="CHANG", format="F13", pillar="P14", hook_id="H002", title="The calf pump (second heart)", secs=41,
 beats=[
  ("0-3","CHANG","If you sit for hours every afternoon, your calves take the afternoon off. Try this.","YOUR SECOND HEART",f"{ST} | CU calves rising on bottom step, hand on rail | CU low angle"),
  ("3-12","CHANG","Your calf muscles squeeze the veins in your legs. Every squeeze pushes blood back up toward your heart. It's called the calf muscle pump.","The calf muscle pump","same | anatomy inset: calf veins + one-way valves animation | inset top-right"),
  ("12-18","CHANG","Sit all day, and the pump is quiet. Walking and heel raises switch it on.","Sitting = quiet pump","same | Chang on sofa, then standing | quick cuts"),
  ("18-29","CHANG","Hold the rail. Breathe out, rise onto your toes. Pause. Lower slowly. Fifteen. Then walk to the mailbox.","Up · pause · slow down · ×15","same | heel raises, then walks to mailbox | medium-full"),
  ("29-35","CHANG","One calf swollen, red and painful? That's not for exercise. That's for your doctor, today.","Swollen red calf? Doctor today.","same | CU | CU"),
  ("35-40","CHANG","Comment STRONG for the chair builder.","Comment STRONG","same | at mailbox, points | medium"),
 ],
 move=True, tags=["heel_raise"], safety="Rail support; DVT red flag spoken. Caption add-on stop rule.",
 regression="Seated heel raises.", cta="STRONG",
 caption="Comment STRONG for the 8-minute Chair Builder.\nYour calf muscle pump: calf contractions squeeze the deep veins and, with one-way valves, push blood back toward the heart. Walking and heel raises switch it on.\nOne swollen, red, painful calf can mean a clot. See a doctor the same day.",
 ig=["#strengthtraining","#calfraises","#over60","#physiology"], tt=["#physiology","#over60","#strengthtraining","#calfraises"],
 yt="Your Legs Have a 'Second Heart': The Calf Muscle Pump", ev=["E47"],
 note="Standard physiology (D-grade), stated mechanistically, no disease claim; DVT red flag.", bit="", wink=False, thumb="2ND HEART", music="warm acoustic"),

